import React from 'react';

const Card = ({ text, category }) => {
  return (
    <div className="w-full max-w-md aspect-[3/4] bg-raw-bone p-8 flex flex-col justify-between shadow-[20px_20px_0px_0px_rgba(0,240,255,1)]">
      <div className="flex justify-between items-start">
        <span className="text-raw-onyx font-archivo text-xs uppercase tracking-tighter">
          RAW<span className="text-raw-cyan">.</span> SESSION
        </span>
        <span className="px-2 py-1 bg-raw-onyx text-raw-bone text-[10px] font-bold uppercase">
          {category}
        </span>
      </div>
      
      <h3 className="text-raw-onyx font-archivo text-3xl leading-tight uppercase">
        "{text}"
      </h3>

      <div className="border-t-2 border-raw-onyx pt-4 text-[10px] text-raw-onyx/50 font-inter uppercase tracking-widest">
        Responde com honestidade ou passa a vez.
      </div>
    </div>
  );
};

export default Card;
